import { useState, useEffect, useCallback } from 'react';

export const useChat = (chatRoom, config = {}) => {
    const {
        storageKeyPrefix = 'chatMessages',
        canSwitchRooms = true,
        availableRooms = []
    } = config;

    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(true);
    const [currentRoom, setCurrentRoom] = useState(chatRoom || 'default');
    const [canSwitch, setCanSwitch] = useState(canSwitchRooms);
    const [currentUserAuthor, setCurrentUserAuthor] = useState('');
    const [isRecording, setIsRecording] = useState(false);
    const [mediaRecorder, setMediaRecorder] = useState(null);
    const [recordingTime, setRecordingTime] = useState(0);
    const [recordingInterval, setRecordingInterval] = useState(null);

    // Определяем текущего пользователя
    useEffect(() => {
        const demoRole = localStorage.getItem('demoRole');
        let author = 'Пользователь';

        if (demoRole === 'admin-moderator' || demoRole === 'developer' || demoRole === 'super-admin') {
            author = 'Админ';
        } else if (demoRole === 'user1') {
            author = 'Пользователь 1';
        } else if (demoRole === 'user2') {
            author = 'Пользователь 2';
        }

        setCurrentUserAuthor(author);
    }, []);

    // Получаем ключ хранилища
    const getStorageKey = useCallback((room) => {
        return `${storageKeyPrefix}_${room}`;
    }, [storageKeyPrefix]);

    // Загрузка сообщений
    const loadMessages = useCallback((room) => {
        const key = getStorageKey(room);
        const savedMessages = localStorage.getItem(key);

        if (savedMessages) {
            setMessages(JSON.parse(savedMessages));
        } else {
            // Начальное сообщение
            const initialMessage = {
                id: 1,
                author: 'Админ',
                content: getWelcomeMessage(room),
                timestamp: new Date().toISOString()
            };
            setMessages([initialMessage]);
            localStorage.setItem(key, JSON.stringify([initialMessage]));
        }
        setLoading(false);
    }, [getStorageKey]);

    // Инициализация
    useEffect(() => {
        loadMessages(currentRoom);
    }, [currentRoom, loadMessages]);

    // Функция для получения приветственного сообщения
    const getWelcomeMessage = (room) => {
        // Можно расширить через конфиг
        return `Добро пожаловать в чат${room !== 'default' ? ' ' + room : ''}!`;
    };

    // Смена комнаты
    const changeRoom = useCallback((room) => {
        if (!canSwitch) return;
        setCurrentRoom(room);
    }, [canSwitch]);

    // Отправка сообщения
    const sendMessage = useCallback((content) => {
        if (!content.trim()) return;

        const message = {
            id: Date.now(),
            author: currentUserAuthor,
            content: content.trim(),
            timestamp: new Date().toISOString()
        };

        const updatedMessages = [...messages, message];
        setMessages(updatedMessages);

        localStorage.setItem(getStorageKey(currentRoom), JSON.stringify(updatedMessages));

        return message;
    }, [messages, currentUserAuthor, currentRoom, getStorageKey]);

    // Редактирование сообщения
    const editMessage = useCallback((msgId, newContent) => {
        if (!newContent.trim()) return;

        const updatedMessages = messages.map(msg =>
            msg.id === msgId
                ? { ...msg, content: newContent.trim(), edited: true }
                : msg
        );

        setMessages(updatedMessages);
        localStorage.setItem(getStorageKey(currentRoom), JSON.stringify(updatedMessages));
    }, [messages, currentRoom, getStorageKey]);

    // Удаление сообщения
    const deleteMessage = useCallback((msgId) => {
        const messageToDelete = messages.find(msg => msg.id === msgId);
        if (!messageToDelete || messageToDelete.author !== currentUserAuthor) {
            alert('Вы можете удалять только свои сообщения');
            return false;
        }

        if (!window.confirm('Удалить это сообщение?')) return false;

        const updatedMessages = messages.filter(msg => msg.id !== msgId);
        setMessages(updatedMessages);
        localStorage.setItem(getStorageKey(currentRoom), JSON.stringify(updatedMessages));

        return true;
    }, [messages, currentUserAuthor, currentRoom, getStorageKey]);

    // Загрузка файла
    const uploadFile = useCallback((file) => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();

            reader.onload = (event) => {
                const message = {
                    id: Date.now(),
                    author: currentUserAuthor,
                    content: file.name,
                    fileUrl: event.target.result,
                    fileType: file.type,
                    fileName: file.name,
                    timestamp: new Date().toISOString(),
                    type: 'file'
                };

                const updatedMessages = [...messages, message];
                setMessages(updatedMessages);
                localStorage.setItem(getStorageKey(currentRoom), JSON.stringify(updatedMessages));

                resolve(message);
            };

            reader.onerror = () => reject(reader.error);
            reader.readAsDataURL(file);
        });
    }, [messages, currentUserAuthor, currentRoom, getStorageKey]);

    // Начало записи голосового
    const startRecording = useCallback(async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const recorder = new MediaRecorder(stream);
            const chunks = [];

            recorder.ondataavailable = (e) => {
                chunks.push(e.data);
            };

            recorder.onstop = () => {
                const blob = new Blob(chunks, { type: 'audio/webm' });
                const reader = new FileReader();

                reader.onload = (event) => {
                    const message = {
                        id: Date.now(),
                        author: currentUserAuthor,
                        content: 'Голосовое сообщение',
                        fileUrl: event.target.result,
                        fileType: 'audio/webm',
                        timestamp: new Date().toISOString(),
                        type: 'voice'
                    };

                    const updatedMessages = [...messages, message];
                    setMessages(updatedMessages);
                    localStorage.setItem(getStorageKey(currentRoom), JSON.stringify(updatedMessages));
                };

                reader.readAsDataURL(blob);
                stream.getTracks().forEach(track => track.stop());
            };

            recorder.start();
            setMediaRecorder(recorder);
            setIsRecording(true);
            setRecordingTime(0);

            const interval = setInterval(() => {
                setRecordingTime(prev => prev + 1);
            }, 1000);
            setRecordingInterval(interval);
        } catch (error) {
            console.error('Ошибка доступа к микрофону:', error);
            alert('Не удалось получить доступ к микрофону');
        }
    }, [currentUserAuthor, currentRoom, messages, getStorageKey]);

    // Остановка записи
    const stopRecording = useCallback(() => {
        if (mediaRecorder && mediaRecorder.state !== 'inactive') {
            mediaRecorder.stop();
            setIsRecording(false);
            if (recordingInterval) {
                clearInterval(recordingInterval);
                setRecordingInterval(null);
            }
        }
    }, [mediaRecorder, recordingInterval]);

    // Форматирование времени записи
    const formatRecordingTime = (seconds) => {
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    return {
        // Состояние
        messages,
        loading,
        currentRoom,
        canSwitch,
        currentUserAuthor,
        isRecording,
        recordingTime,

        // Действия
        changeRoom,
        sendMessage,
        editMessage,
        deleteMessage,
        uploadFile,
        startRecording,
        stopRecording,
        formatRecordingTime,
        getStorageKey,
        loadMessages
    };
};

export default useChat;
